import { z } from 'zod';

import { UserSkillId } from './skill-identity';
export { UserSkillId } from './skill-identity';
import { SkillPackageSource, SkillInstallTask, SkillInstallCandidate } from './skill-community';
import { SkillReviewLocale } from './skill-install-config';
const LegacySkillSource = z.discriminatedUnion('type', [
  z.object({ type: z.literal('folder'), path: z.string().min(1).max(4096) }),
  z.object({ type: z.literal('git'), url: z.string().min(1).max(2048), ref: z.string().min(1).max(200).optional() }),
]);

const LegacySkillCandidate = z.object({
  subdir: z.string(), name: z.string(),
  state: z.enum(['pending', 'validating', 'reviewing', 'repairing', 'ready', 'failed', 'installed', 'skipped']).default('pending'),
  description: z.string().optional(),
  message: z.string().default(''),
  error: z.string().optional(),
  reviewReason: z.string().optional(),
  repairs: z.array(z.string()).default([]),
  originalSha256: z.string().optional(),
  installedSha256: z.string().optional(),
});

export const LegacySkillInstallation = z.object({
  installationId: z.string(),
  state: z.enum(['preparing', 'downloading', 'validating', 'awaiting-selection', 'reviewing', 'repairing', 'awaiting-confirmation', 'committing', 'succeeded', 'partially-succeeded', 'failed', 'cancelled']),
  source: LegacySkillSource,
  subdir: z.string().optional(),
  commit: z.string().optional(),
  candidates: z.array(LegacySkillCandidate),
  skillId: UserSkillId.optional(),
  message: z.string(),
  repairs: z.array(z.string()),
  tokensUsed: z.number().nonnegative(),
  originalSha256: z.string().optional(),
  installedSha256: z.string().optional(),
  createdAt: z.number(),
  updatedAt: z.number(),
  validation: z.literal('static-only'),
});

export const InstalledUserSkill = z.object({
  skillId: UserSkillId,
  name: z.string(),
  description: z.string(),
  installationId: z.string(),
  source: LegacySkillSource,
  subdir: z.string(),
  commit: z.string().optional(),
  installedAt: z.number(),
  originalSha256: z.string(),
  installedSha256: z.string(),
  repairs: z.array(z.string()),
  validation: z.literal('static-only'),
});
export type InstalledUserSkill = z.infer<typeof InstalledUserSkill>;

export const SkillSource = SkillPackageSource;
export type SkillSource = z.infer<typeof SkillSource>;
export const SkillInstallRequest = z.object({ source: SkillPackageSource,
  locale: SkillReviewLocale.optional(),
  subdir: z.string().max(1024).optional(), target: z.object({ scope: z.literal('user') }).strict().default({ scope: 'user' }),
  expectedInstanceId: z.string().optional(), expectedRevisionId: z.string().optional(),
}).strict().refine(value => Boolean(value.expectedInstanceId) === Boolean(value.expectedRevisionId), 'Update identity requires an expected revision');
export type SkillInstallRequest = z.infer<typeof SkillInstallRequest>;
export const SkillCandidate = SkillInstallCandidate;
export type SkillCandidate = z.infer<typeof SkillCandidate>;
export const SkillInstallation = SkillInstallTask;
export type SkillInstallation = z.infer<typeof SkillInstallation>;
